from pathlib import Path
import re,sys,collections
sys.stdout.reconfigure(encoding=\"utf-8\")
root=Path(\"docs/planning\")
files=[p for p in root.rglob(\"*.md\") if \"archive\" not in p.parts]
txt={str(p.relative_to(root)):p.read_text(encoding=\"utf-8\") for p in files}
patterns={\"REQ\":r\"REQ-[A-Z]+-\\d+\",\"AC\":r\"AC-(?:P\\d+[a-z]?|V\\d+)-\\d+[a-z]?\",\"TEST\":r\"TEST-[A-Z]+(?:-[A-Z]+)?-\\d+[a-z]?|TEST-RC-S\\d+\",\"CAP\":r\"CAP-\\d+\",\"D\":r\"\\bD(?:[1-9]|1\\d|2[0-8])\\b\",\"R\":r\"\\bR(?:[1-9]|1\\d|2[0-3])\\b\",\"V\":r\"\\bV(?:[1-9]|[12]\\d|3[0-5])\\b\",\"U\":r\"\\bU(?:10|[1-9])\\b\"}
for k,pat in patterns.items():
 defs=set()
 for f,s in txt.items():
  for line in s.splitlines():
   m=re.match(r\"\\s*\\|\\s*(\"+pat+r\")\\s*\\|\",line)
   if m:defs.add(m.group(1))
 uses=set(x for s in txt.values() for x in re.findall(pat,s))
 missing=sorted(uses-defs)
 print(k,\"defs\",len(defs),\"uses\",len(uses),\"not-table-defined\",len(missing),missing[:100])
'@ | python -"

